-- 2026-11-12 1.6.2 第 3 条层次结构与性能指标逐行拆分
begin;
create temp table _kb16(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kb16 values (60, $kb16$[{"t":"list","id":"a1-1-6-2-b1","imp":"core","items":["^^3.5 英寸软盘片，其上、下两面各被划分为80 个磁道，每个磁道被划分为18 个扇区，每个扇区的存储容量固定为512 字节。^^","1、==硬盘存储器==：==特点 - 既是输入设备也是输出设备==；","- ==非易失性存储器==，可长期保存二进制信息；","- ==可读可写==，成本低、可靠性高、容量大；","- ==磁盘属于磁存储器而非半导体存储器==，通过磁表面存储记录数据。 硬盘数据的三个参数：柱面号（磁道号）、磁头号（记录面号）、扇区号。 技术指标 容量：影响因素为总磁头数、柱面数（磁道数）、扇区数和每扇区容量。","2、==存储器的速度排序==：^^由快到慢^^：寄存器→Cache→主存储器→外存储器→后备存储器（磁带库、光盘库）。 为了获取好的性价比，计算机中各种存储器组成层状的塔式结构，取长补短、协调工作。","3、==存储器的层次结构与性能指标==","^^存储器结构层次^^：","==第一层：通用寄存器堆==","第二层：指令与数据缓冲栈","第三层：高速缓冲存储器","第四层：主存储器（DRAM）","第五层：联机外部存储器（硬磁盘机）","第六层：脱机外部存储器（磁带、光盘存储器等）","主要性能指标：存储容量、存取时间、存储周期、存储器带宽。","存储容量的基本单位是字节（Byte），1KB = 1024B = 2^10B。","4、==硬盘存储器的性能指标==：^^容量^^：==以 GB 为单位==。 平均访问时间：在几 ms 至几十 ms 之间，由硬盘旋转速度（平均等待时间）、磁头寻道时间（平均寻道时间）和数据传输速率决定。 缓存容量：原则上越大越好，通常为几十 MB，硬盘的 Cache 采用 DRAM 芯片制成。 数据传输速率：外部传输速率指主机从硬盘缓存读出（或写入）数据的速度，与接口类型有关；内部传输速率指硬盘在盘片上读写数据的速度，转速越高内部传输速率越快。","5、==硬盘的主要性能指标==：","① ==平均等待时间 硬盘转一圈时间的一半==，要会从硬盘的转速推算出平均等待时间。","② 平均存取时间（几 ms 至几十 ms 之间） 寻道时间 + 旋转等待时间 + 数据传输时间。","③ 平均存取时间由旋转速度、磁头的寻道时间和数据的传输速率决定。","④ ==硬盘的传输速率指硬盘外部和内部数据的传输速率==，外部速率大于内部速率。","6、==硬盘数据定位：3D寻址与硬盘接口==：硬盘上定位一块数据采用3D寻址——柱面号、扇区号、磁头号。","^^1) 磁道^^：==硬盘表面由外向里分成若干个同心圆==。","^^2) 柱面^^：==所有单碟上相同磁道的组合==。硬盘与主机的接口：在主机内存和硬盘缓存之间提供数据传输的高速通道；类型有IDE（PATA）、SCSI、光纤通道、SATA（150MB/s~300MB/s）。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-6-2-b2","imp":"core","kind":"tip","text":"==硬盘存储容量 = 磁头数（盘面数） × 柱面数（每面磁道数） × 每道扇区数 × 每扇区字节数（512B）== 【例题】：某硬盘有 4 个盘片（8 个有效盘面），每个盘面有 1024 个磁道（柱面），每个磁道有 64 个扇区，扇区大小为 512B，则总容量为：`8 × 1024 × 64 × 512B = 268,435,456 B = 256 MB`。","title":"考向复习提示：机械硬盘容量计算公式"},{"t":"callout","id":"a1-1-6-2-b3","imp":"core","kind":"trap","text":"硬盘厂商标称容量采用==十进制（1 TB = 10^12 字节 = 1000 GB）==，而 Windows 操作系统计算容量采用==二进制（1 TiB = 2^40 字节 ≈ 1.0995 × 10^12 字节）==；因此一块标称为 1 TB 的硬盘在系统里实际识别约为 `10^12 / (1024^3) ≈ 931 GB`；常考选择题考查为什么硬盘买回家容量缩水！","title":"高频易错陷阱：硬盘厂商十进制标称 vs 操作系统二进制容量"}]$kb16$::jsonb, $kb16se$A1-1.6.2 存储器存储结构，各项性能参数设置，数据分布，容量计算。 3.5 英寸软盘片，其上、下两面各被划分为80 个磁道，每个磁道被划分为18 个扇区，每个扇区的存储容量固定为512 字节。 1、硬盘存储器：特点 - 既是输入设备也是输出设备； - 非易失性存储器，可长期保存二进制信息； - 可读可写，成本低、可靠性高、容量大； - 磁盘属于磁存储器而非半导体存储器，通过磁表面存储记录数据。 硬盘数据的三个参数：柱面号（磁道号）、磁头号（记录面号）、扇区号。 技术指标 容量：影响因素为总磁头数、柱面数（磁道数）、扇区数和每扇区容量。 2、存储器的速度排序：由快到慢：寄存器→Cache→主存储器→外存储器→后备存储器（磁带库、光盘库）。 为了获取好的性价比，计算机中各种存储器组成层状的塔式结构，取长补短、协调工作。 3、存储器的层次结构与性能指标 存储器结构层次： 第一层：通用寄存器堆 第二层：指令与数据缓冲栈 第三层：高速缓冲存储器 第四层：主存储器（DRAM） 第五层：联机外部存储器（硬磁盘机） 第六层：脱机外部存储器（磁带、光盘存储器等） 主要性能指标：存储容量、存取时间、存储周期、存储器带宽。 存储容量的基本单位是字节（Byte），1KB = 1024B = 2^10B。 4、硬盘存储器的性能指标：容量：以 GB 为单位。 平均访问时间：在几 ms 至几十 ms 之间，由硬盘旋转速度（平均等待时间）、磁头寻道时间（平均寻道时间）和数据传输速率决定。 缓存容量：原则上越大越好，通常为几十 MB，硬盘的 Cache 采用 DRAM 芯片制成。 数据传输速率：外部传输速率指主机从硬盘缓存读出（或写入）数据的速度，与接口类型有关；内部传输速率指硬盘在盘片上读写数据的速度，转速越高内部传输速率越快。 5、硬盘的主要性能指标： ① 平均等待时间 硬盘转一圈时间的一半，要会从硬盘的转速推算出平均等待时间。 ② 平均存取时间（几 ms 至几十 ms 之间） 寻道时间 + 旋转等待时间 + 数据传输时间。 ③ 平均存取时间由旋转速度、磁头的寻道时间和数据的传输速率决定。 ④ 硬盘的传输速率指硬盘外部和内部数据的传输速率，外部速率大于内部速率。 6、硬盘数据定位：3D寻址与硬盘接口：硬盘上定位一块数据采用3D寻址——柱面号、扇区号、磁头号。 1) 磁道：硬盘表面由外向里分成若干个同心圆。 2) 柱面：所有单碟上相同磁道的组合。硬盘与主机的接口：在主机内存和硬盘缓存之间提供数据传输的高速通道；类型有IDE（PATA）、SCSI、光纤通道、SATA（150MB/s~300MB/s）。 考向复习提示：机械硬盘容量计算公式 硬盘存储容量 = 磁头数（盘面数） × 柱面数（每面磁道数） × 每道扇区数 × 每扇区字节数（512B） 【例题】：某硬盘有 4 个盘片（8 个有效盘面），每个盘面有 1024 个磁道（柱面），每个磁道有 64 个扇区，扇区大小为 512B，则总容量为：8 × 1024 × 64 × 512B = 268,435,456 B = 256 MB。 高频易错陷阱：硬盘厂商十进制标称 vs 操作系统二进制容量 硬盘厂商标称容量采用十进制（1 TB = 10^12 字节 = 1000 GB），而 Windows 操作系统计算容量采用二进制（1 TiB = 2^40 字节 ≈ 1.0995 × 10^12 字节）；因此一块标称为 1 TB 的硬盘在系统里实际识别约为 10^12 / (1024^3) ≈ 931 GB；常考选择题考查为什么硬盘买回家容量缩水！$kb16se$);
do $$
declare r record; old_rev record; v_rev integer;
begin
  for r in select node_id, blocks, search_text from _kb16 loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
